def clean(df):
    df = df.copy()
    # strip whitespace for text columns
    for col in ['species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].where(df[col].isna(), df[col].astype(str).str.strip())
            df[col] = df[col].replace('', pd.NA)
    # normalize species case variants (e.g., chinstrap -> Chinstrap)
    if 'species' in df.columns:
        mapping = {'adelie': 'Adelie', 'chinstrap': 'Chinstrap', 'gentoo': 'Gentoo'}
        df['species'] = df['species'].apply(lambda x: mapping.get(str(x).strip().lower(), str(x).strip()) if pd.notna(x) else x)
    # island: strip already done, also normalize case if needed
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip()
        # fix any remaining case/space variants to allowed values
        allowed_island = {'biscoe': 'Biscoe', 'dream': 'Dream', 'torgersen': 'Torgersen'}
        df['island'] = df['island'].apply(lambda x: allowed_island.get(x.lower(), x) if pd.notna(x) and x.lower() != 'nan' else x)
    # convert numbers written as text
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # fix body_mass_g out_of_range (e.g., 3650000 -> 3650, likely extra zeros / grams vs mg)
    if 'body_mass_g' in df.columns:
        mask = df['body_mass_g'] > 6500
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000
    # drop exact duplicates (keep id column)
    df = df.drop_duplicates()
    return df

def answer(df):
    # ensure island is cleaned for grouping
    if 'island' in df.columns:
        df = df.copy()
        df['island'] = df['island'].astype(str).str.strip()
        df = df[df['island'].notna() & (df['island'] != '') & (df['island'].str.lower() != 'nan')]
    # count penguins per island (penguin_id is unique)
    if 'penguin_id' in df.columns:
        counts = df.groupby('island')['penguin_id'].count()
    else:
        counts = df.groupby('island').size()
    # drop missing group keys and format
    result = {}
    for k, v in counts.items():
        if pd.isna(k) or str(k).strip() == '':
            continue
        result[str(k)] = int(v)
    return result
